/**
 * Merge overlapping or touching intervals.
 *
 * Sorts by start, then sweeps left-to-right merging any interval whose
 * start is ≤ the current end (touching counts as overlap).
 *
 * @param {number[][]} intervals  – array of [start, end] pairs (may be unsorted)
 * @returns {number[][]}  – merged, non-overlapping intervals sorted by start
 */
function mergeIntervals(intervals) {
  if (intervals.length === 0) return [];

  const sorted = intervals.slice().sort((a, b) => a[0] - b[0]);
  const merged = [sorted[0].slice()];

  for (let i = 1; i < sorted.length; i++) {
    const [start, end] = sorted[i];
    const last = merged[merged.length - 1];

    if (start <= last[1]) {
      // Overlapping or touching — extend if needed
      last[1] = Math.max(last[1], end);
    } else {
      // Disjoint — start a new interval
      merged.push([start, end]);
    }
  }

  return merged;
}

module.exports = { mergeIntervals };

